<?php require_once __DIR__.'/_auth.php'; function dt_or_null($value){$value=trim((string)$value);return $value===''?null:str_replace('T',' ',$value).':00';} function html_dt($value){return $value?date('Y-m-d\TH:i',strtotime($value)):'';} if($_SERVER['REQUEST_METHOD']==='POST'){$id=!empty($_POST['id'])?(int)$_POST['id']:0;$data=[trim($_POST['event_name']??''),trim($_POST['venue_name']??''),trim($_POST['event_date']??'')?:null,dt_or_null($_POST['portal_available_from']??''),dt_or_null($_POST['portal_available_until']??''),$_POST['queue_visibility']??'venue',trim($_POST['notes']??''),!empty($_POST['is_active'])?1:0]; if($data[0]!==''&&$data[1]!==''){ if($id){$stmt=db()->prepare('UPDATE events SET event_name=?,venue_name=?,event_date=?,portal_available_from=?,portal_available_until=?,queue_visibility=?,notes=?,is_active=? WHERE id=?');$stmt->execute([...$data,$id]);} else {$stmt=db()->prepare('INSERT INTO events (event_name,venue_name,event_date,portal_available_from,portal_available_until,queue_visibility,notes,is_active) VALUES (?,?,?,?,?,?,?,?)');$stmt->execute($data);}} header('Location: /admin/events.php');exit;} $edit=!empty($_GET['edit'])?get_event((int)$_GET['edit']):null; $events=db()->query('SELECT e.*, (SELECT COUNT(*) FROM song_requests sr WHERE sr.event_id=e.id) AS request_count FROM events e ORDER BY event_date DESC,id DESC')->fetchAll(); ?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Events Admin</title><link rel="stylesheet" href="/assets/style.css"></head><body><nav class="topnav"><a href="/">Portal</a><a href="/admin/">Requests</a><a href="/admin/events.php">Events</a><a href="/admin/?logout=1">Logout</a></nav><main class="container"><div class="card"><h1><?= $edit?'Edit Event':'Create Event' ?></h1><form method="post"><?php if($edit): ?><input type="hidden" name="id" value="<?= (int)$edit['id'] ?>"><?php endif; ?><label>Event name *</label><input name="event_name" required value="<?= h($edit['event_name']??'') ?>" placeholder="Example: 80s & 90s Party Night"><label>Venue name *</label><input name="venue_name" required value="<?= h($edit['venue_name']??'') ?>" placeholder="Example: The Crown Inn"><label>Event date</label><input type="date" name="event_date" value="<?= h($edit['event_date']??'') ?>"><label>Portal available from</label><input type="datetime-local" name="portal_available_from" value="<?= h(html_dt($edit['portal_available_from']??null)) ?>"><label>Portal available until</label><input type="datetime-local" name="portal_available_until" value="<?= h(html_dt($edit['portal_available_until']??null)) ?>"><label>Request queue visibility</label><select name="queue_visibility"><?php $qv=$edit['queue_visibility']??'venue'; ?><option value="venue" <?= $qv==='venue'?'selected':'' ?>>Defined by venue</option><option value="public" <?= $qv==='public'?'selected':'' ?>>Public</option><option value="private" <?= $qv==='private'?'selected':'' ?>>Private / admin only</option></select><label>Notes</label><textarea name="notes" placeholder="Internal event notes"><?= h($edit['notes']??'') ?></textarea><label><input style="width:auto" type="checkbox" name="is_active" value="1" <?= !empty($edit['is_active'])?'checked':'' ?>> Active / available for portal selection</label><button class="btn btn-primary" type="submit"><?= $edit?'Save Event':'Create Event' ?></button><?php if($edit): ?><a class="btn btn-secondary" href="/admin/events.php">Cancel Edit</a><?php endif; ?></form></div><div class="card" style="margin-top:16px"><h2>Events</h2><table class="table"><thead><tr><th>Event</th><th>Date</th><th>Available</th><th>Status</th><th>Requests</th><th>Actions</th></tr></thead><tbody><?php foreach($events as $e): ?><tr><td><strong><?= h($e['event_name']) ?></strong><br><?= h($e['venue_name']) ?></td><td><?= h($e['event_date']) ?></td><td><?= h($e['portal_available_from']) ?><br><?= h($e['portal_available_until']) ?></td><td><?= $e['is_active']?'<span class="status-played">Active</span>':'<span class="status-rejected">Inactive</span>' ?></td><td><?= (int)$e['request_count'] ?></td><td><a class="btn btn-gold" href="/admin/events.php?edit=<?= (int)$e['id'] ?>">Edit</a><a class="btn btn-secondary" href="/admin/?event=<?= (int)$e['id'] ?>">Requests</a><a class="btn btn-green" href="/request.php?event=<?= (int)$e['id'] ?>" target="_blank">Guest Link</a></td></tr><?php endforeach; ?><?php if(!$events): ?><tr><td colspan="6">No events yet.</td></tr><?php endif; ?></tbody></table></div></main></body></html>
